    public boolean isPowerOfThree(int n) {
        if (n <= 0) {
            return false;
        }
        // The largest power of 3 that fits in a 32-bit signed integer is 3^19 = 1162261467.
        // If n is a power of 3, it must divide this maximum value evenly.
        return 1162261467 % n == 0;
    }
}

